    var prepend_nonliteral_value = try tokenized.ParsedSql.initAlloc(alloc, "SELECT array_prepend(status, tags) AS bad_prepend FROM docs WHERE _id = 'doc:a'");
    defer prepend_nonliteral_value.deinit(alloc);
